const STY = (bg, l, t, w, h, fs) => `position:absolute;left:${l}px;top:${t}px;width:${w}px;height:${h}px;display:flex;align-items:center;justify-content:center;text-align:center;border-radius:46px;box-shadow:0 26px 40px -14px rgba(0,0,0,.5),inset 0 4px 0 rgba(255,255,255,.5);background:${bg};color:#0b1020;font-weight:800;font-size:${fs}px;line-height:1.1;opacity:0;`;
const G1 = `linear-gradient(180deg,color-mix(in srgb,var(--acc) 72%,#fff),var(--acc) 55%,color-mix(in srgb,var(--acc) 84%,#000))`;
const G2 = `linear-gradient(180deg,color-mix(in srgb,var(--acc2) 72%,#fff),var(--acc2) 55%,color-mix(in srgb,var(--acc2) 84%,#000))`;

root.innerHTML = `
  <div id="tit" style="position:absolute;top:80px;width:100%;text-align:center;color:#fff;font-size:52px;font-weight:900;opacity:0;">RIEMANN HYPOTHESIS</div>
  <div id="sub" style="position:absolute;top:150px;width:100%;text-align:center;color:var(--acc);font-size:36px;font-weight:800;opacity:0;">167-YEAR CHALLENGE</div>

  <div id="main" style="${STY(G1, 170, 320, 600, 240, 70)}">UNSOLVED</div>

  <div id="c1" style="${STY(G2, 80, 640, 370, 140, 42)}">HUMAN MIND</div>
  <div id="c2" style="${STY(G2, 490, 640, 370, 140, 42)}">AI SYSTEMS</div>

  <div id="res1" style="${STY(G1, 80, 820, 370, 140, 40)}">PRIME THEORY</div>
  <div id="res2" style="${STY(G1, 490, 820, 370, 140, 40)}">CRYPTOGRAPHY</div>

  <svg style="position:absolute;top:0;left:0;width:940px;height:1060px;fill:none;stroke:#fff;stroke-width:6;stroke-linecap:round;opacity:0.2;z-index:-1">
    <path id="l1" d="M265 640 L470 560" />
    <path id="l2" d="M675 640 L470 560" />
  </svg>
`;

const tit = root.querySelector('#tit');
const sub = root.querySelector('#sub');
const main = root.querySelector('#main');
const c1 = root.querySelector('#c1');
const c2 = root.querySelector('#c2');
const r1 = root.querySelector('#res1');
const r2 = root.querySelector('#res2');
const ls = [1, 2].map(i => root.querySelector('#l' + i));

function frame(t, p, d) {
  const limit = 0.55;
  const pt = clamp(p / limit);

  // Header intro
  tit.style.opacity = clamp(pt * 10);
  tit.style.transform = `translateY(${lerp(30, 0, E_OUT(clamp(pt * 4)))}px)`;
  sub.style.opacity = clamp((pt - 0.1) * 10);

  // Main card: UNSOLVED -> SOLVED transition
  const mainP = clamp(pt * 3);
  main.style.opacity = clamp(mainP * 5);
  main.style.transform = `scale(${spr(pt, 0, 0.8, 12)})`;

  if (pt > 0.45) {
    main.style.background = G2;
    main.textContent = 'SOLVED';
    main.style.transform = `scale(${spr(pt, 0.45, 0.7, 10)})`;
  }

  // AI & Human cards converge
  const convP = clamp((pt - 0.2) * 2.5);
  c1.style.opacity = clamp(convP * 5);
  c1.style.transform = `translateX(${lerp(-100, 0, E_OUT(convP))}px)`;
  c2.style.opacity = clamp(convP * 5);
  c2.style.transform = `translateX(${lerp(100, 0, E_OUT(convP))}px)`;

  // Connection lines
  ls.forEach(l => {
    l.style.opacity = clamp((convP - 0.5) * 2) * 0.2;
  });

  // Final result cards
  const resP = clamp((pt - 0.7) * 3.3);
  r1.style.opacity = clamp(resP * 5);
  r1.style.transform = `translateY(${lerp(40, 0, E_OUT(resP))}px)`;
  r2.style.opacity = clamp(resP * 5);
  r2.style.transform = `translateY(${lerp(40, 0, E_OUT(resP))}px)`;
}
